}

fn history(
    entry_count: usize,
) -> (
    ChatComposerHistory,
    AppEventSender,
    UnboundedReceiver<AppEvent>,
) {
    let (tx, rx) = unbounded_channel();
    let tx = AppEventSender::new(tx);
    let mut history = ChatComposerHistory::new();
    history.set_metadata(thread_id(/*value*/ 1), /*log_id*/ 42, entry_count);
